<script setup>
import {onBeforeUnmount,onMounted,ref,watch} from 'vue';
import axios from 'axios';
import {RefreshCw,ChevronRight,Building2} from '@lucide/vue';
const props=defineProps({apiBase:String,sessionToken:String,visible:{type:Boolean,default:true}});const emit=defineEmits(['open','open-main']);
const items=ref([]),agencies=ref([]),search=ref(''),agency=ref('all'),loading=ref(false),error=ref(''),nextPage=ref(null);let generation=0,timer,lastLoaded=0,loadedScope='';
const currentScope=()=>`${agency.value}:${search.value.trim()}`;
async function load({append=false,force=false}={}){if(!props.visible)return;const scope=currentScope();if(!append&&!force&&scope===loadedScope&&Date.now()-lastLoaded<60000)return;const request=++generation,token=props.sessionToken;loading.value=true;error.value='';if(scope!==loadedScope&&!append)items.value=[];
 try{const {data}=await axios.get(`${props.apiBase}/clients`,{params:{q:search.value.trim()||undefined,agencyId:agency.value,page:append?nextPage.value:0},headers:{'X-Quick-View-Session':token},withCredentials:true});if(request!==generation||token!==props.sessionToken)return;items.value=append?[...items.value,...data.clients]:data.clients||[];agencies.value=data.agencies||agencies.value;nextPage.value=data.nextPage??null;lastLoaded=Date.now();loadedScope=scope;}
 catch(e){if(request!==generation)return;if([401,403].includes(e.response?.status)){items.value=[];agencies.value=[];}error.value=e.response?.data?.error?.message||'Your clients could not be loaded. Try again.';}
 finally{if(request===generation)loading.value=false;}}
function open(item){emit('open',{clientId:item.clientId||item.id,agencyId:item.agencyId});}
watch(search,()=>{clearTimeout(timer);timer=setTimeout(()=>load({force:true}),250);});watch(agency,()=>load({force:true}));watch(()=>props.visible,value=>{if(value)load();});watch(()=>props.sessionToken,()=>{generation++;items.value=[];agencies.value=[];lastLoaded=0;loadedScope='';if(props.visible)load({force:true});});onMounted(()=>load());onBeforeUnmount(()=>{generation++;clearTimeout(timer);items.value=[];});
</script>
<template><section class="mobile-clients" aria-label="My Clients"><header><label>Find a client<input v-model="search" type="search" aria-label="Search My Clients" placeholder="Initials or name"/></label><button type="button" aria-label="Refresh My Clients" :disabled="loading" @click="load({force:true})"><RefreshCw :size="18"/></button></header><label class="mc-agency">Agency<select v-model="agency" aria-label="My Clients agency"><option value="all">All agencies</option><option v-for="a in agencies" :key="a.id" :value="String(a.id)">{{ a.name }}</option></select></label><p v-if="loading&&!items.length" role="status">Loading your clients…</p><p v-if="error" role="alert">{{error}} <button @click="load({force:true})">Try again</button></p><button v-for="item in items" :key="`${item.agencyId}:${item.id}`" type="button" class="mc-row" @click="open(item)"><img v-if="item.agencyLogoUrl" :src="item.agencyLogoUrl" alt=""/><Building2 v-else :size="26"/><span><strong>{{item.maskedName}}<template v-if="item.age!=null"> · Age {{item.age}}</template></strong><small>{{item.agencyName}}</small></span><ChevronRight :size="18"/></button><p v-if="!loading&&!error&&!items.length">No authorized clients match this view.</p><button v-if="nextPage!==null" class="mc-more" :disabled="loading" @click="load({append:true,force:true})">{{loading?'Loading…':'Load more clients'}}</button></section></template>
<style scoped>.mobile-clients{background:white;padding:16px;color:#1b385d;min-width:0}.mobile-clients header{display:flex;align-items:flex-end;gap:8px}.mobile-clients header label{flex:1;min-width:0;display:grid;gap:5px;font-size:12px}.mobile-clients input,.mobile-clients select{font:16px system-ui;padding:10px;min-width:0;width:100%;box-sizing:border-box;border:1px solid #d8e3f6;border-radius:9px;background:white;color:inherit}.mobile-clients button{font:inherit;color:inherit;cursor:pointer}.mobile-clients header button,.mc-more{border:1px solid #d8e3f6;background:#edf4ff;border-radius:9px;padding:10px}.mc-agency{display:flex;align-items:center;gap:10px;font-size:12px;margin:12px 0}.mc-agency select{flex:1}.mc-row{display:flex;align-items:center;gap:12px;width:100%;padding:17px 0;text-align:left;border:0;border-bottom:1px solid #e5ebf5;background:white}.mc-row>img{width:38px;height:38px;object-fit:contain}.mc-row>span{display:grid;gap:6px;flex:1;min-width:0}.mc-row strong{font-size:14px;overflow-wrap:anywhere}.mc-row small,.mobile-clients p{font-size:12px;color:#657d9c}.mobile-clients [role=alert]{color:#923b3b}.mobile-clients button:focus-visible{outline:3px solid #7da5ef;outline-offset:2px}.mc-more{margin:14px 0;width:100%}</style>
